<?php
include_once(realpath(dirname(__FILE__) . '/../php/path.php'));
include_once(ROOT_SRC_PATH . '/session.php');
include_once(ROOT_SRC_PATH . '/config.php');
include_once(ROOT_SRC_PATH . '/check_admin.php');

// Handle adding a new physical copy with auto-generated barcode
if (isset($_POST['add_copy'])) {
    $book_id = (int)$_POST['book_id'];
    $status = trim($_POST['status']);
    
    // Programmatically generate a unique, collision-resistant barcode
    $barcode = 'BC-' . strtoupper(substr(md5(uniqid(mt_rand(), true)), 0, 8));
    
    if ($book_id > 0) {
        $stmt = $db_connection->prepare("INSERT INTO Copies (book_id, barcode, status) VALUES (?, ?, ?)");
        $stmt->bind_param('iss', $book_id, $barcode, $status);
        $stmt->execute();
        header("Location: copies.php");
        exit;
    }
}

// Handle updating copy status
if (isset($_POST['update_status'])) {
    $copy_id = (int)$_POST['copy_id'];
    $status = trim($_POST['status']);
    
    $stmt = $db_connection->prepare("UPDATE Copies SET status = ? WHERE copy_id = ?");
    $stmt->bind_param('si', $status, $copy_id);
    $stmt->execute();
    header("Location: copies.php");
    exit;
}

// Handle search filtering for existing copies
$search = trim($_GET['search'] ?? '');
if (!empty($search)) {
    $search_param = "%$search%";
    $stmt = $db_connection->prepare("
      SELECT c.copy_id, c.barcode, c.status, c.book_id, b.title
      FROM Copies c
      JOIN Books b ON c.book_id = b.book_id
      WHERE b.title LIKE ? OR c.barcode LIKE ?
      ORDER BY b.title, c.barcode
    ");
    $stmt->bind_param('ss', $search_param, $search_param);
    $stmt->execute();
    $copies = $stmt->get_result();
} else {
    $copies = $db_connection->query("
      SELECT c.copy_id, c.barcode, c.status, c.book_id, b.title
      FROM Copies c
      JOIN Books b ON c.book_id = b.book_id
      ORDER BY b.title, c.barcode
    ");
}

// Fetch active books for the searchable datalist
$books = $db_connection->query("SELECT book_id, title FROM Books WHERE is_active = 1 ORDER BY title");
$books_array = [];
while ($b = $books->fetch_assoc()) {
    $books_array[] = $b;
}
?>
