  <!-- JavaScript to map datalist selection to hidden book_id -->
  <script>
    const bookInput = document.querySelector('input[name="book_id_display"]');
    const bookIdVal = document.getElementById('book_id_val');
    const options = document.querySelectorAll('#bookOptions option');

    bookInput.addEventListener('input', function() {
      let val = this.value;
      bookIdVal.value = '';
      options.forEach(function(opt) {
        if (opt.value === val) {
          bookIdVal.value = opt.getAttribute('data-id');
        }
      });
    });
  </script>
